import{_ as i,o as a,c as t,a5 as e}from"./chunks/framework.BYXPg_yw.js";const c=JSON.parse('{"title":"오디오","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/audio.md","filePath":"ko/software/audio.md","lastUpdated":1793350928000}'),l={name:"ko/software/audio.md"};function p(n,s,o,h,d,k){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="오디오" tabindex="-1">오디오 <a class="header-anchor" href="#오디오" aria-label="Permalink to &quot;오디오&quot;">​</a></h1><p>로봇은 마이크로 녹음하고 스피커로 음원 파일을 재생합니다. 녹음과 재생은 <code>8081</code> 포트, 녹음 파일 다운로드는 <code>8080</code> 포트로 보내는 HTTP 요청입니다. 둘 다 로봇 웹 계정(<code>rb</code> / <code>rainbow2026</code>)으로 HTTP Basic 인증을 하고, 본문은 JSON 입니다.</p><h2 id="audio-devices" tabindex="-1">쓰이는 마이크와 스피커 <a class="header-anchor" href="#audio-devices" aria-label="Permalink to &quot;쓰이는 마이크와 스피커 {#audio-devices}&quot;">​</a></h2><p>로봇은 마이크와 스피커를 하나씩만 쓰며, 어느 것을 쓸지 스스로 정합니다.</p><table tabindex="0"><thead><tr><th>로봇</th><th>마이크</th><th>스피커</th></tr></thead><tbody><tr><td>PTZ 페이로드 장착</td><td>PTZ 카메라 마이크</td><td>PTZ 카메라 스피커</td></tr><tr><td>PTZ 페이로드 없음</td><td>로봇 오디오 입력에 꽂은 마이크</td><td>로봇 스피커</td></tr></tbody></table><p>PTZ 카메라가 켜지거나 빠지면 약 5초 안에 전환됩니다. 녹음·재생 전에 쓰이는 장치를 확인하세요. <code>input</code> 과 <code>output</code> 이 <code>ptz</code>, <code>robot</code>, <code>none</code> 중 하나로 나옵니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/status</span></span></code></pre></div><ul><li><strong>로봇 마이크</strong> — 로봇 오디오 입력은 아무것도 꽂지 않아도 장치로 잡히므로 <code>mic_present</code> 만으로는 마이크가 있는지 알 수 없습니다. <code>mic_signal</code> 을 보세요. 소리가 들어오면 <code>1</code>, 거의 무음이라 잭이 비었을 수 있으면 <code>0</code> 입니다. 상태를 조회할 때 1분에 한 번까지만 다시 재므로, 마이크를 꽂고 1분 뒤에 확인하세요. 마이크는 녹음을 시작하기 전에 꽂으세요 — 녹음 중에 빼면 나머지는 무음으로 저장됩니다.</li><li><strong>로봇 스피커</strong> — 스피커 앰프가 꺼져 있으면 소리가 나지 않습니다. <strong>정비 → 전원 / 시스템</strong>에서 <code>스피커 앰프 (12V)</code>(CAN-FD 로봇은 <code>스피커 앰프</code>)를 켜세요 — <a href="/RBQ/nightly/ko/manual/gui/maintenance.html#power">정비</a>를 참고하세요. PTZ 카메라 스피커는 자체 앰프가 있습니다.</li></ul><h2 id="audio-record" tabindex="-1">녹음 <a class="header-anchor" href="#audio-record" aria-label="Permalink to &quot;녹음 {#audio-record}&quot;">​</a></h2><ol><li><p>녹음을 시작합니다. 로봇이 응답한 순간부터 녹음되므로 응답을 받은 뒤 말하세요. 응답에 파일 경로가 담겨 옵니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/record</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;state&quot;:&quot;start&quot;,&quot;source&quot;:&quot;mic&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># {&quot;path&quot;:&quot;20261026/mic_20261026_143000.wav&quot;, ...}</span></span></code></pre></div><p>마이크가 없으면 <code>no microphone</code> 으로 실패합니다.</p></li><li><p>녹음을 끝냅니다. 이렇게 해야 파일이 완성됩니다 — 녹음 중인 파일은 길이가 0초로 읽힙니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/record</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;state&quot;:&quot;stop&quot;}&#39;</span></span></code></pre></div></li><li><p>파일을 받습니다. 같은 포트의 <code>GET /api/audio/list</code> 가 녹음 목록을 돌려줍니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rec.wav</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &#39;http://192.168.0.10:8080/api/audio/file?path=20261026/mic_20261026_143000.wav&#39;</span></span></code></pre></div></li></ol><p>파일 하나는 30분이 지나면 닫힙니다. 녹음 중에 다시 시작하면 앞 파일을 닫고 새 파일로 녹음합니다.</p><h2 id="audio-play" tabindex="-1">음원 재생 <a class="header-anchor" href="#audio-play" aria-label="Permalink to &quot;음원 재생 {#audio-play}&quot;">​</a></h2><ol><li><p>파일을 base64 로 나눠 올립니다. 조각마다 바이트 <code>offset</code> 과 파일 전체 크기 <code>total</code> 을 함께 보내며, 전체 50 MB 까지입니다. 마지막 조각이 도착하면 로봇이 재생용으로 변환하고 경로를 돌려줍니다. 10분을 넘는 부분은 잘립니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/upload</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;:&quot;alarm&quot;,&quot;offset&quot;:0,&quot;total&quot;:&lt;bytes&gt;,&quot;data&quot;:&quot;&lt;base64&gt;&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 마지막 조각: {&quot;path&quot;:&quot;library/alarm.wav&quot;, ...}</span></span></code></pre></div></li><li><p>재생합니다. <code>&quot;loop&quot;:true</code> 면 최대 30분까지 반복합니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rb:rainbow2026</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.0.10:8081/api/audio/play</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;path&quot;:&quot;library/alarm.wav&quot;,&quot;loop&quot;:false}&#39;</span></span></code></pre></div></li><li><p>같은 요청에 <code>{&quot;state&quot;:&quot;stop&quot;}</code> 을 보내 멈춥니다. 다른 파일을 재생하면 재생 중이던 파일을 대신합니다.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>재생은 운용 앱의 <code>워키토키</code>와 스피커 하나를 같이 씁니다. 운용 앱이 연결돼 있다가 끊기면 재생도 함께 멈춥니다.</p></div><h2 id="audio-ptz" tabindex="-1">PTZ 카메라로 실시간 음성 <a class="header-anchor" href="#audio-ptz" aria-label="Permalink to &quot;PTZ 카메라로 실시간 음성 {#audio-ptz}&quot;">​</a></h2><p>로봇 자체 인터페이스는 파일 녹음·재생만 합니다. 실시간 음성은 PTZ 카메라(<code>192.168.0.100</code>)를 직접 사용하세요.</p><ul><li><strong>마이크</strong> — 카메라의 <code>profile4</code> RTSP 스트림 (<code>rtsp://&lt;user&gt;:&lt;password&gt;@192.168.0.100:554/profile4/media.smp</code>)에 마이크 트랙이 들어 있습니다. 이를 받거나, 스트림을 저장해 녹음합니다.</li><li><strong>스피커</strong> — 카메라의 ONVIF 오디오 백채널을 엽니다. 같은 <code>profile4</code> 에 <code>Require: www.onvif.org/ver20/backchannel</code> 헤더를 붙여 접속하고 <code>sendonly</code> 트랙을 SETUP 한 뒤 PLAY 합니다. PLAY 응답 뒤에 보내는 소리는 바로 나옵니다. G.711 μ-law(PCMU) 8 kHz 를 20 ms 마다 160바이트씩 보내고, 말이 없는 동안에도 무음 프레임을 계속 보내세요. 다 쓰면 세션을 닫습니다(TEARDOWN).</li></ul><p>카메라 스피커는 25 W 입니다. 오디오 설정은 SUNAPI 레퍼런스를 참고하세요.</p><p>로봇도 파일 재생과 운용 앱의 <code>워키토키</code>에 같은 백채널을 쓰므로 둘을 동시에 쓰지 마세요. 로봇은 소리가 끝나고 2초 뒤 백채널을 닫습니다. 카메라 계정과 SUNAPI 는 <a href="/RBQ/nightly/ko/software/ptz-camera-api.html">PTZ 카메라</a>를 참고하세요.</p>`,19)])])}const u=i(l,[["render",p]]);export{c as __pageData,u as default};
